    @Version
    class Child extends Parent {
    }
    context.checking(new Expectations() {

        {
            oneOf(mockChildType).getCorrespondingClass();
            inSequence(sequence);
            will(returnValue(Child.class));
            oneOf(mockChildType).superclass();
            inSequence(sequence);
