    file.createNewFile();
    Assert.assertTrue(file.exists());
    final List<FileContent> files = new ArrayList<FileContent>();
    files.add(new FileContent('I', "1023", "1", "2", FULLY_QUALIFIED_CLASSNAME, "{data1}"));
