    String[] lines = content.getDisplayLines();
    assertEquals(4, lines.length);
    assertEquals("Apache Isis - a ", lines[0]);
    assertEquals("framework that ", lines[1]);
    assertEquals("exposes behaviourally ", lines[2]);
